sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.hrRemarks = "";
    c.successMessage = "";
    c.errorMessage = "";


    c.approve = function() {

        c.successMessage = "";
        c.errorMessage = "";

        if (!c.hrRemarks) {
            c.errorMessage =
                "Please enter HR remarks before approving.";
            return;
        }

        c.server.get({
            action: 'approve',
            hrRemarks: c.hrRemarks
        }).then(function(response) {

            c.data = response.data;

            if (response.data.actionSuccess) {

                c.successMessage =
                    response.data.actionMessage;

                c.hrRemarks = "";

            }

        });
    };


    c.reject = function() {

        c.successMessage = "";
        c.errorMessage = "";

        if (!c.hrRemarks) {
            c.errorMessage =
                "Please enter HR remarks before rejecting.";
            return;
        }

        c.server.get({
            action: 'reject',
            hrRemarks: c.hrRemarks
        }).then(function(response) {

            c.data = response.data;

            if (response.data.actionSuccess) {

                c.successMessage =
                    response.data.actionMessage;

                c.hrRemarks = "";

            }

        });
    };

};

sp_widget.css:
.hr-leave-detail-page {
  max-width: 1150px;
  margin: 0 auto;
  padding: 34px 30px 60px;
  min-height: 100vh;
  background: #f7f9fc;
  color: #0f1b45;
  font-family: Arial, sans-serif;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  color: #0f1b45;
}

.page-header p {
  margin: 0;
  color: #7d879c;
  font-size: 13px;
}

.back-link {
  color: #1769e0;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 18px;
}

.summary-card {
  background: #fff;
  border: 1px solid #e2e7ef;
  border-radius: 13px;
  padding: 18px;
  box-shadow: 0 3px 12px rgba(15,27,69,.04);
}

.summary-card span,
.info-grid span,
.hr-remarks-result span {
  display: block;
  color: #8993a7;
  font-size: 10px;
  margin-bottom: 7px;
}

.summary-card strong {
  color: #0f1b45;
  font-size: 14px;
}

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-bottom: 18px;
}

.detail-card,
.action-card,
.result-card {
  background: #fff;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 4px 14px rgba(15,27,69,.05);
}

.detail-card h3,
.action-card h3,
.result-card h3 {
  margin: 0 0 18px;
  color: #0f1b45;
  font-size: 15px;
  font-weight: 700;
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.info-grid strong {
  color: #25314f;
  font-size: 12px;
}

.full-card {
  margin-bottom: 18px;
}

.reason-box {
  min-height: 72px;
  padding: 15px;
  background: #f7f9fc;
  border: 1px solid #e1e6ee;
  border-radius: 9px;
  color: #3b4762;
  font-size: 12px;
  line-height: 1.6;
}

.reason-box.emergency {
  background: #fff7ed;
  border-color: #fed7aa;
}

.status-pill,
.decision-status {
  display: inline-block;
  padding: 6px 12px;
  border-radius: 16px;
  font-size: 10px !important;
  font-weight: 700;
}

.status-pending {
  background: #fff2d9;
  color: #d98500 !important;
}

.status-approved,
.decision-approved {
  background: #dcfce7;
  color: #15803d !important;
}

.status-rejected,
.decision-rejected {
  background: #fee2e2;
  color: #dc2626 !important;
}

.action-card {
  border-left: 4px solid #0b8793;
  margin-top: 20px;
}

.action-header p {
  color: #7d879c;
  font-size: 11px;
  margin-bottom: 18px;
}

.action-card label {
  font-size: 11px;
  color: #45516b;
  margin-bottom: 7px;
}

.remarks-box {
  min-height: 110px;
  border-radius: 9px;
  resize: vertical;
}

.action-footer {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding-top: 18px;
  margin-top: 18px;
  border-top: 1px solid #edf1f5;
}

.approve-btn,
.reject-btn {
  padding: 10px 20px;
  border-radius: 8px;
  border: none;
  font-size: 12px;
  font-weight: 700;
}

.approve-btn {
  background: #0b8793;
  color: #fff;
}

.approve-btn:hover {
  background: #08727b;
}

.reject-btn {
  background: #fee2e2;
  color: #c62828;
}

.reject-btn:hover {
  background: #fecaca;
}

.result-card {
  margin-top: 20px;
}

.hr-remarks-result {
  margin-top: 18px;
  padding: 14px;
  background: #f7f9fc;
  border-radius: 9px;
}

.hr-remarks-result p {
  margin: 0;
  color: #34415d;
  font-size: 12px;
}

.success-message {
  margin-top: 18px;
  padding: 13px 16px;
  border-radius: 9px;
  background: #e5f7ed;
  color: #16724d;
}

.error-message,
.message-box {
  margin-top: 18px;
  padding: 13px 16px;
  border-radius: 9px;
  background: #fee2e2;
  color: #b91c1c;
}

@media(max-width: 800px) {

  .summary-grid {
    grid-template-columns: 1fr 1fr;
  }

  .detail-grid {
    grid-template-columns: 1fr;
  }

  .page-header {
    display: block;
  }

  .back-link {
    display: inline-block;
    margin-top: 12px;
  }

}

sp_widget.script:
(function() {

    data.requestFound = false;
    data.message = "";
    data.leave = {};

    var requestSysId = $sp.getParameter('sys_id');

    if (!requestSysId) {
        data.message = "No leave request was selected.";
        return;
    }


    var gr = new GlideRecord(
        'x_snc_unified_hr_0_leave_request'
    );

    if (!gr.get(requestSysId)) {
        data.message = "Leave request not found.";
        return;
    }


    data.requestFound = true;


    // -------------------------
    // PROCESS HR ACTION
    // -------------------------

    if (input && input.action) {

        var remarks = input.hrRemarks || "";

        if (input.action == 'approve') {

            gr.setValue('status', 'approved');
            gr.setValue('hr_remarks', remarks);

            gr.update();

            data.actionSuccess = true;
            data.actionMessage =
                "Leave request approved successfully.";
        }


        if (input.action == 'reject') {

            gr.setValue('status', 'rejected');
            gr.setValue('hr_remarks', remarks);

            gr.update();

            data.actionSuccess = true;
            data.actionMessage =
                "Leave request rejected successfully.";
        }
    }


    // Reload record after update
    gr.get(requestSysId);


    data.leave = {

        sys_id:
            gr.getUniqueValue(),

        number:
            gr.getDisplayValue('number'),

        requested_by:
            gr.getDisplayValue('requested_by'),

        department:
            gr.getDisplayValue('department'),

        leave_type:
            gr.getDisplayValue('leave_type'),

        start_date:
            gr.getDisplayValue('start_date'),

        end_date:
            gr.getDisplayValue('end_date'),

        number_of_leave_days:
            gr.getDisplayValue('number_of_leave_days'),

        reason:
            gr.getDisplayValue('reason'),

        emergency_reason:
            gr.getDisplayValue('emergency_reason'),

        hod_remarks:
            gr.getDisplayValue('hod_remarks'),

        hr_remarks:
            gr.getDisplayValue('hr_remarks'),

        status:
            gr.getDisplayValue('status'),

        status_value:
            gr.getValue('status'),

        approval_group:
            gr.getDisplayValue('approval_group'),

        current_approver:
            gr.getDisplayValue('current_approver'),

        applied_on:
            gr.getDisplayValue('applied_on')

    };

})();
